/* Forks a child process to execute a command via execvp
 * and waits for it to complete. */
static void execute_command(char** args) {
  if (args[0] == NULL)
    return;

  pid_t pid = fork();

  if (pid == 0) {
    /* Child process */
    /* flawfinder:ignore */
    execvp(args[0], args);
    perror("execvp failed");
    exit(EXIT_FAILURE);
  } else if (pid == -1) {
    /* Fork failed */
    perror("fork failed");
    exit(EXIT_FAILURE);
  } else {
    /* Parent process */
    waitpid(pid, NULL, 0);
  }
}

